chmod +x docker/railway-start.sh && mkdir -p .railway && cat > .railway/railway.ts <<'EOF'
// Railway Infrastructure as Code for this Healthchecks instance.
// Preview with `railway config plan`, apply with `railway config apply`.
// Setup steps, costs and limitations: .railway/README.md
import { defineRailway, github, preserve, project, service, volume } from "railway/iac";

export default defineRailway(() => {
  // SQLite database lives on this volume. One small volume is the cheapest
  // persistent option (no separate always-on Postgres service to pay for).
  const data = volume("healthchecks-data");

  const web = service("healthchecks", {
    source: github("albertogrande/healthchecks", { branch: "master" }),
    // Build context is the repository root; the Dockerfile lives in docker/.
    build: { builder: "DOCKERFILE", dockerfilePath: "docker/Dockerfile" },
    start: "/opt/healthchecks/docker/railway-start.sh",
    healthcheck: "/api/v3/status/",
    healthcheckTimeout: 300,
    deploy: {
      // sendalerts/sendreports run inside this container, so it must never sleep.
      sleepApplication: false,
      restartPolicyType: "ALWAYS",
    },
    volumeMounts: { "/data": data },
    env: {
      // uWSGI listens on 8000; tells Railway where to route traffic and healthchecks.
      PORT: "8000",
      SITE_ROOT: "https://${{RAILWAY_PUBLIC_DOMAIN}}",
      // Railway's deploy healthcheck uses this Host header.
      ALLOWED_HOSTS: "${{RAILWAY_PUBLIC_DOMAIN}},healthcheck.railway.app",
      // Railway terminates TLS and sets X-Forwarded-Proto.
      SECURE_PROXY_SSL_HEADER: "HTTP_X_FORWARDED_PROTO,https",
      DEBUG: "False",
      DB_NAME: "/data/hc.sqlite",
      // Volumes are mounted root-owned; the image runs as user "hc" by default.
      RAILWAY_RUN_UID: "0",
      // Fewer web workers = less RAM = lower bill. Plenty for a small instance.
      UWSGI_PROCESSES: "2",
      // Hobby plan blocks outbound SMTP, so sign-up links can't be emailed.
      // Create accounts with `manage.py createsuperuser` instead.
      REGISTRATION_OPEN: "False",
      // Set once with `railway variables --set SECRET_KEY=...`; never commit it.
      SECRET_KEY: preserve(),
    },
  });

  return project("healthchecks", {
    resources: [web, data],
  });
});
EOF
cat > .railway/package.json <<'EOF'
{
  "name": "healthchecks-railway-config",
  "private": true,
  "type": "module",
  "description": "Railway Infrastructure as Code SDK used by `railway config plan/apply`.",
  "devDependencies": {
    "railway": "3.16.0"
  }
}
EOF
printf 'node_modules/\n' > .railway/.gitignore
cd .railway && npm install --ignore-scripts 2>&1 | tail -2; ls

node --version && cat > /tmp/eval-railway.mjs <<'EOF'
const cfgPath = process.argv[2];
const mod = await import(cfgPath);
const iac = await import(new URL("../work/repo/.railway/node_modules/railway/dist/iac/index.js", "file:///tmp/").href);
const ctx = iac.createRailwayContext({ environment: "production", command: "plan" });
const def = await mod.default(ctx, iac.project);
console.log(JSON.stringify(def, null, 2));
EOF
node --experimental-strip-types /tmp/eval-railway.mjs /work/repo/.railway/railway.ts 2>&1 | head -80
